  function dashboardFilter(status){state.dashboard.status=status;$('#dashboard-site-list').innerHTML=dashboardCards();document.querySelectorAll('.dashboard-filters button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.status===status?'true':'false'));$('#dashboard-enterprises').scrollIntoView({block:'start'});rememberCursor();save();}
  function dashboardPeriod(){const d=state.dashboard;openSheet('Период результатов',`<p class="muted">Период применяется к завершённым визитам и последним результатам ПБО. Черновики доступны за все даты.</p><label class="field-label" for="dashboard-from">С даты</label><input class="search-input" id="dashboard-from" type="date" value="${esc(d.from)}"><label class="field-label" for="dashboard-to">По дату</label><input class="search-input" id="dashboard-to" type="date" value="${esc(d.to)}"><button class="primary" data-action="dashboard-apply-period">Применить период</button><button class="text-button dashboard-reset-period" data-action="dashboard-all-dates">Все даты</button>`);}
