  function openSheet(title,body){if($('#sheet').hidden)dialogFocus=document.activeElement;$('#screen').inert=true;$('#tabs').inert=true;$('#sheet').innerHTML=`<section class="sheet-panel" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><header class="sheet-header"><h2 id="sheet-title">${title}</h2><button class="icon-button" data-action="close-sheet" aria-label="Закрыть">${icon('x')}</button></header>${body}</section>`;$('#sheet').hidden=false;($('#sheet input')||$('#sheet button')).focus();}
  function closeSheet(focus=true){$('#sheet').hidden=true;$('#sheet').replaceChildren();$('#screen').inert=false;$('#tabs').inert=false;if(focus&&dialogFocus?.isConnected)dialogFocus.focus();}
  function pboOptions(query=''){const options=PBOS.filter(p=>(p.id+' '+p.name).toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')));return options.map(p=>`<button class="pbo-option" role="option" aria-selected="${state.pbo===p.id}" data-action="select-pbo" data-id="${p.id}"><span>${p.id}</span><strong>${esc(p.name)}</strong>${state.pbo===p.id?icon('check-circle','green-icon'):icon('caret-right')}</button>`).join('')||'<p class="empty">Предприятия не найдены. Попробуйте другой номер или название.</p>';}
  function calendar(){const [y,m]=calendarMonth.split('-').map(Number),first=new Date(y,m-1,1),offset=(first.getDay()+6)%7,days=new Date(y,m,0).getDate();openSheet('Дата визита',`<div class="calendar-top"><button class="icon-button" data-action="month-prev" aria-label="Предыдущий месяц">${icon('arrow-left')}</button><span>${first.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</span><button class="icon-button" data-action="month-next" aria-label="Следующий месяц">${icon('arrow-right')}</button></div><div class="calendar-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<span>${d}</span>`).join('')}${Array(offset).fill('<span></span>').join('')}${Array.from({length:days},(_,i)=>{const value=calendarMonth+'-'+String(i+1).padStart(2,'0');return `<button data-action="select-date" data-value="${value}" class="${value===state.date?'selected':''} ${value===TODAY?'today':''}" aria-label="${date(value)}" ${value===state.date?'aria-pressed="true"':''}>${i+1}</button>`;}).join('')}</div>`);}
