  function metadata(v){const p=pbo(v.pbo),known=p.id==='3333333';return [['Инициатор',v.creatorId?window.PuskWorkspaceHandoffs?.person(state.workspace,v.creatorId)||v.creatorId:'Не передан в прежних данных'],['ПБО №',p.id],['ПБО название',p.name],['КпП',state.workspace?.people.find(p=>p.id===v.creatorId)?.role==='kpp'?window.PuskWorkspaceHandoffs.person(state.workspace,v.creatorId):known?'Рычков тест 2':'Не указан'],['МпП',known?'рычков тест 6 рычков тест 6':'Не указан'],['ДпП',known?'рычков тест 7 рычков тест 7':'Не указан'],['Директор ПБО',known?'рычков тест 3 рычков тест 3':'Не указан'],['Дата визита',shortDate(v.date)],['Чек-лист',CATALOG.get(CATALOG.identity(v))?.sourceName||CATALOG.visitName(v)],['Статус',v.done?'Завершён':'Предварительный'],...(v.assignmentId?[['Назначение',state.workspace?.assignments.find(a=>a.id===v.assignmentId)?.title||v.assignmentId],['Состав проверки',v.scopeLabel||'Полный аудит'],['Основание','Демонстрационное назначение']]:[])];}
  function reportData(v){const s=summary(v),p=pbo(v.pbo);return {preliminary:!v.done,metadata:metadata(v),falsification:v.done||v.falsificationConfirmed?v.falsification:'Не выбран',summary:s,percent:pct(s.percent),sections:s.sections.map(sec=>({...sec,percent:pct(sec.yes/sec.total*100)})),questions:scopedQuestions(v).map(q=>({...q,answer:v.answers[q.id]||'Без ответа',reasons:v.answers[q.id]==='Нет'?(v.reasons[q.id]||[]):[],comment:v.comments[q.id]||'',photo:v.photos[q.id]}))};}
  async function preparePdf(){disposePdf();const token=pdfToken,v=visit(),width=Math.max(320,$('#pdf-pages').clientWidth),density=Math.min(devicePixelRatio||1,2);try{const bytes=await window.PuskReportPdf.create(reportData(v));if(token!==pdfToken||state.view!=='pdf')return;pdfUrl=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));$('#pdf-open').href=pdfUrl;$('#pdf-open').hidden=false;pdfTask=window.pdfjsLib.getDocument({data:new Uint8Array(bytes),isEvalSupported:false});const doc=await pdfTask.promise;for(let i=1;i<=doc.numPages;i++){if(token!==pdfToken)return;const p=await doc.getPage(i);if(token!==pdfToken)return;const base=p.getViewport({scale:1}),viewport=p.getViewport({scale:width/base.width*density}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);canvas.setAttribute('aria-label',`Страница ${i} из ${doc.numPages}`);const box=document.createElement('div');box.className='pdf-canvas-page';const label=document.createElement('p');label.textContent=`Страница ${i} / ${doc.numPages}`;box.append(canvas,label);$('#pdf-pages').append(box);await p.render({canvasContext:canvas.getContext('2d'),viewport}).promise;}if(token===pdfToken)$('#pdf-status').textContent='';}catch(e){if(token===pdfToken){$('#pdf-status').textContent='Не удалось подготовить PDF. Вернитесь к проверке и попробуйте снова.';console.error(e);}}}
